-- PostgreSQL is authoritative. All marks are integer hundredths.
create schema if not exists private;
revoke all on schema private from public;
create table public.schools(id uuid primary key default gen_random_uuid(),code text not null unique check(code=lower(code)),name text not null,timezone text not null default 'Asia/Kolkata',status text not null default 'active' check(status in ('active','suspended')),public_enabled boolean not null default false,indexing_enabled boolean not null default false);
create table public.subscriptions(school_id uuid primary key references schools(id),plan text not null,starts_at timestamptz not null,ends_at timestamptz not null,teacher_limit int not null check(teacher_limit>=0),student_limit int not null check(student_limit>=0),ai_limit int not null check(ai_limit>=0),storage_limit bigint not null default 1073741824,check(ends_at>starts_at));
create table public.memberships(id uuid primary key,school_id uuid references schools(id),role text not null check(role in ('owner','administrator','teacher','student')),display_name text not null,active boolean not null default true,must_change_password boolean not null default false,credential_version int not null default 1,created_at timestamptz not null default now(),unique(school_id,id),check((role='owner')=(school_id is null)));
create unique index one_owner on memberships(role) where role='owner';
create table private.login_identifiers(school_id uuid not null references schools(id),normalized text not null,display text not null,user_id uuid not null references memberships(id),current boolean not null default true,primary key(school_id,normalized));
create unique index one_current_login on private.login_identifiers(user_id) where current;
create table private.sessions(token_hash text primary key,user_id uuid not null references memberships(id),encrypted_provider_tokens text not null,csrf_hash text not null,created_at timestamptz not null default now(),last_seen_at timestamptz not null default now(),reauthenticated_at timestamptz not null default now(),expires_at timestamptz not null,revoked_at timestamptz,credential_version int not null);
create table public.classes(id uuid primary key default gen_random_uuid(),school_id uuid not null references schools(id),academic_year text not null,name text not null,section text not null,unique(school_id,id),unique(school_id,academic_year,name,section));
create table public.teacher_assignments(school_id uuid not null,teacher_id uuid not null,class_id uuid not null,subject text not null,primary key(teacher_id,class_id,subject),foreign key(school_id,teacher_id) references memberships(school_id,id),foreign key(school_id,class_id) references classes(school_id,id));
create table public.student_registry(student_id uuid primary key,school_id uuid not null,admission_number text,foreign key(school_id,student_id) references memberships(school_id,id),unique(school_id,admission_number),unique(school_id,student_id));
create table public.enrollments(school_id uuid not null,class_id uuid not null,student_id uuid not null,roll text not null,active boolean not null default true,primary key(class_id,student_id),unique(class_id,roll),foreign key(school_id,class_id) references classes(school_id,id),foreign key(school_id,student_id) references student_registry(school_id,student_id));
create table public.audit_events(id uuid primary key default gen_random_uuid(),school_id uuid references schools(id),actor_id uuid not null references memberships(id),actor_role text not null,subject_id uuid,action text not null,reason text,changes jsonb not null default '{}',correlation_id uuid not null default gen_random_uuid(),created_at timestamptz not null default now());
create table private.provisioning(id uuid primary key,school_id uuid not null references schools(id),actor_id uuid not null references memberships(id),kind text not null check(kind in ('administrator','teacher','student')),identity_key text not null,state text not null default 'reserved' check(state in ('reserved','auth_created','active','failed')),auth_id uuid,error_code text,updated_at timestamptz not null default now(),unique(school_id,identity_key));
create table public.import_jobs(id uuid primary key default gen_random_uuid(),school_id uuid not null references schools(id),actor_id uuid not null references memberships(id),checksum text not null,idempotency_key text not null,state text not null default 'preview',created_at timestamptz not null default now(),unique(school_id,actor_id,idempotency_key),unique(school_id,id));
create table public.import_rows(school_id uuid not null,job_id uuid not null,row_number int not null,identity_key text not null,state text not null check(state in ('new','existing','conflict','invalid','reserved','auth_created','active','failed')),student_id uuid,error_code text,preview jsonb not null,primary key(job_id,row_number),foreign key(school_id,job_id) references import_jobs(school_id,id));
create table public.outbox(id uuid primary key default gen_random_uuid(),school_id uuid not null references schools(id),kind text not null,dedup_key text not null unique,payload jsonb not null,status text not null default 'pending' check(status in ('pending','dispatched','processing','done','unavailable','failed')),attempts int not null default 0,available_at timestamptz not null default now(),lease_until timestamptz,run_token uuid,result jsonb,error_code text,created_at timestamptz not null default now());
create index outbox_pending on outbox(available_at) where status in ('pending','dispatched','processing');
create table public.notifications(id uuid primary key default gen_random_uuid(),school_id uuid not null,recipient_id uuid not null,event_key text not null,type text not null,resource_id uuid,metadata jsonb not null default '{}',created_at timestamptz not null default now(),read_at timestamptz,foreign key(school_id,recipient_id) references memberships(school_id,id),unique(recipient_id,event_key));
create table private.ai_usage(school_id uuid not null references schools(id),month date not null,kind text not null,used int not null default 0,primary key(school_id,month,kind));
create or replace function private.me() returns uuid language sql stable set search_path='' as $$select auth.uid()$$;
create or replace function private.school() returns uuid language sql stable security definer set search_path='' as $$select school_id from public.memberships where id=auth.uid() and active$$;
create or replace function private.role() returns text language sql stable security definer set search_path='' as $$select m.role from public.memberships m left join public.schools s on s.id=m.school_id where m.id=auth.uid() and m.active and (m.role='owner' or s.status='active')$$;
create or replace function private.staff(s uuid) returns boolean language sql stable security definer set search_path='' as $$select coalesce(private.school()=s and private.role() in ('administrator','teacher'),false)$$;
create or replace function private.assigned(c uuid,subject_filter text default null) returns boolean language sql stable security definer set search_path='' as $$select coalesce(private.role()='administrator' and private.school()=(select school_id from public.classes where id=c),false) or exists(select 1 from public.teacher_assignments a where a.teacher_id=auth.uid() and a.class_id=c and (subject_filter is null or a.subject=subject_filter) and a.school_id=private.school())$$;
create or replace function private.student_access(u uuid) returns boolean language sql stable security definer set search_path='' as $$select coalesce(private.role()='administrator' and exists(select 1 from public.memberships where id=u and school_id=private.school()),false) or exists(select 1 from public.enrollments e where e.student_id=u and e.active and private.assigned(e.class_id))$$;
create or replace function private.require_access(s uuid,write_new boolean default false) returns void language plpgsql security definer set search_path='' as $$begin if private.school() is distinct from s or private.role() is null then raise exception 'FORBIDDEN' using errcode='42501';end if;if write_new and not exists(select 1 from public.subscriptions where school_id=s and now()>=starts_at and now()<ends_at) then raise exception 'SUBSCRIPTION_EXPIRED';end if;end$$;
create or replace function private.audit(s uuid,action text,subject uuid,reason text default null,changes jsonb default '{}') returns void language plpgsql security definer set search_path='' as $$begin if changes::text ~* '(password|token|secret|answer|body)' then raise exception 'UNSAFE_AUDIT_FIELDS';end if;insert into public.audit_events(school_id,actor_id,actor_role,subject_id,action,reason,changes)values(s,auth.uid(),private.role(),subject,action,reason,changes);end$$;
create function public.create_class(p jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare s uuid:=private.school();c uuid;begin perform private.require_access(s,true);if private.role()<>'administrator' then raise exception 'FORBIDDEN' using errcode='42501';end if;insert into public.classes(school_id,academic_year,name,section)values(s,p->>'academicYear',p->>'name',p->>'section')returning id into c;perform private.audit(s,'class.created',c);return c;end$$;
create function public.assign_teacher(p jsonb) returns void language plpgsql security definer set search_path='' as $$declare s uuid:=private.school();begin perform private.require_access(s,true);if private.role()<>'administrator' or not exists(select 1 from public.memberships where id=(p->>'teacherId')::uuid and school_id=s and role='teacher' and active) then raise exception 'FORBIDDEN' using errcode='42501';end if;insert into public.teacher_assignments(school_id,teacher_id,class_id,subject)values(s,(p->>'teacherId')::uuid,(p->>'classId')::uuid,p->>'subject')on conflict do nothing;perform private.audit(s,'teacher.assigned',(p->>'teacherId')::uuid);end$$;
-- All exposed tables have RLS; write access is exclusively through checked RPCs.
